use std::path::Path;
use std::fs;

fn main() {
    let manifest_dir = std::env::var("CARGO_MANIFEST_DIR").unwrap();
    let manifest_path = Path::new(&manifest_dir);

    // Load .env file generated by bundle-tenant.py (if present)
    // Falls back gracefully when building without the bundler
    let env_path = manifest_path.join(".env");
    if env_path.exists() {
        let env_content = fs::read_to_string(&env_path).unwrap_or_default();
        for line in env_content.lines() {
            let line = line.trim();
            if line.starts_with("TENANT_CONFIG=") {
                let value = line["TENANT_CONFIG=".len()..].trim();
                // Remove surrounding quotes if present
                let value = value.trim_matches('"').trim_matches('\'');
                std::env::set_var("TENANT_CONFIG", value);
                break;
            }
        }
    }

    // Track tenant config changes for rebuild
    // TENANT_CONFIG is set by bundle-tenant.py via .env
    // Falls back to legacy default for backward compatibility
    let tenant_config_path = std::env::var("TENANT_CONFIG")
        .unwrap_or_else(|_| manifest_path.join("../tenant-configs/default.json").to_string_lossy().into_owned());

    let config_path = Path::new(&tenant_config_path);
    if config_path.exists() {
        println!("cargo:rerun-if-changed={}", config_path.display());

        // Read and copy tenant config to OUT_DIR for runtime inclusion
        let out_dir = std::env::var("OUT_DIR").unwrap();
        let dest_path = Path::new(&out_dir).join("tenant-config.json");
        fs::copy(config_path, &dest_path)
            .expect("Failed to copy tenant config to OUT_DIR");

        // Parse to validate JSON
        let config_str = fs::read_to_string(config_path)
            .expect("Failed to read tenant config");
        let config: serde_json::Value = serde_json::from_str(&config_str)
            .expect("Tenant config is not valid JSON");

        // Emit env var for runtime access to the config file path
        println!("cargo:rustc-env=TENANT_CONFIG_PATH={}", dest_path.display());

        // Also embed the config JSON content as an env var so any crate can read it at compile time
        println!("cargo:rustc-env=TENANT_CONFIG_JSON={}", config_str);

        // Copy the tenant config to a fixed location that all workspace crates can include_str! from
        let shared_dest = manifest_path.join("tenant-config-embedded.json");
        fs::write(&shared_dest, &config_str).expect("Failed to write shared tenant config");

        // Generate Rust module with embedded config for compile-time inclusion
        generate_tenant_config_module(&config_str, &Path::new(&out_dir));

        // Template tauri.conf.json with tenant-specific values
        let tenant_id = config["tenant"]["id"].as_str().unwrap_or("default");
        let commercial_name = config["tenant"]["commercialName"].as_str().unwrap_or("MindLedger");

        template_tauri_conf(tenant_id, commercial_name);
    }

    tauri_build::build()
}

fn template_tauri_conf(tenant_id: &str, commercial_name: &str) {
    let manifest_dir = std::env::var("CARGO_MANIFEST_DIR").unwrap();
    let tauri_conf_path = Path::new(&manifest_dir).join("tauri.conf.json");
    let content = fs::read_to_string(&tauri_conf_path).expect("Failed to read tauri.conf.json");
    
    // Parse and modify
    let mut conf: serde_json::Value = serde_json::from_str(&content).expect("Invalid tauri.conf.json");
    
    conf["identifier"] = serde_json::Value::String(format!("com.mindledger.{}.desktop", tenant_id));
    conf["productName"] = serde_json::Value::String(commercial_name.to_string());
    conf["app"]["windows"][0]["title"] = serde_json::Value::String(commercial_name.to_string());
    
    // Write back (tauri-build reads this)
    let new_content = serde_json::to_string_pretty(&conf).expect("Failed to serialize tauri.conf.json");
    fs::write(&tauri_conf_path, new_content).expect("Failed to write templated tauri.conf.json");
}

/// Generate a Rust module with embedded tenant config for compile-time inclusion
fn generate_tenant_config_module(config_str: &str, out_dir: &Path) {
    let module_content = format!(
        r#"// Auto-generated by build.rs - DO NOT EDIT
/// Embedded tenant configuration JSON
pub const TENANT_CONFIG_JSON: &str = {json_str};
"#,
        json_str = serde_json::to_string(config_str).expect("Failed to serialize config as string literal")
    );
    
    let module_path = out_dir.join("tenant_config.rs");
    fs::write(&module_path, module_content).expect("Failed to write tenant_config.rs");
    
    // Emit the path so the library crate can include it
    println!("cargo:rustc-env=TENANT_CONFIG_RS_PATH={}", module_path.display());
}